// Validate CeoN8nTaskDispatch contract & initialize Ops State
const body = $input.first().json.body || $input.first().json;

if (!body.taskId || !body.objective) {
  throw new Error("Invalid task dispatch: taskId and objective are mandatory.");
}

// Enforce security invariants
const constraints = body.constraints || [];
const allowedTools = body.allowedTools || [];

// Check if WhatsApp is illegally requested
if (allowedTools.includes("whatsapp") || JSON.stringify(body).toLowerCase().includes("whatsapp")) {
  throw new Error("Security Violation: WhatsApp integration is strictly disabled in WebsiteBanja.");
}

return {
  json: {
    taskId: body.taskId,
    objective: body.objective,
    priority: body.priority || "medium",
    constraints,
    allowedTools,
    approvalRequired: Boolean(body.approvalRequired),
    tenantId: body.tenantId || null,
    leadId: body.leadId || null,
    input: body.input || {},
    actions: [],
    results: {},
    failures: [],
    evidence: [],
    status: "in_progress",
    startTime: new Date().toISOString()
  }
};
